using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Runtime.InteropServices;
using System.Web.Script.Serialization;
using DualBoot.Setup;
namespace DualBoot.Installer {
 public sealed class SecureBootNative {
  readonly NativeServices services=new NativeServices();readonly NativeFirmware firmware=new NativeFirmware();
  public static string Root {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),@"DualBoot\SecureBoot");}}
  static void Administrator(){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))throw new InvalidOperationException("Execute o aplicativo como administrador.");}
  static void Protect(){Administrator();string parent=Path.GetDirectoryName(Root);SafeFiles.Plain(parent);SafeFiles.Plain(Root);Directory.CreateDirectory(Root);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));Directory.SetAccessControl(Root,acl);}
  public string SessionDirectory(SecureBootSession s){if(s==null||!SecureBootWorkflow.Hex(s.Id,32))throw new InvalidDataException("ID de sessão inválido.");return SafeFiles.Under(Root,s.Id);}
  static byte[] ReadBounded(string path,long limit){SafeFiles.Plain(path);using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){long size=stream.Length;if(size<1||size>limit||size>int.MaxValue)throw new InvalidDataException("Arquivo ausente ou excessivo.");byte[] data=new byte[(int)size];int at=0;while(at<data.Length){int got=stream.Read(data,at,data.Length-at);if(got==0)throw new IOException("Arquivo truncado durante a leitura.");at+=got;}if(stream.ReadByte()!=-1||stream.Length!=size)throw new IOException("Arquivo mudou durante a leitura.");return data;}}
  void SaveSession(SecureBootSession s){SecureBootWorkflow.Validate(s);SecureInstallerEngine.SaveJson(s,SafeFiles.Under(SessionDirectory(s),"session.json"));}
  SecureBootSession Reload(SecureBootSession s){string path=SafeFiles.Under(SessionDirectory(s),"session.json");var loaded=new JavaScriptSerializer{MaxJsonLength=2*1024*1024}.Deserialize<SecureBootSession>(new UTF8Encoding(false,true).GetString(ReadBounded(path,2*1024*1024)));SecureBootWorkflow.Validate(loaded);if(s.Id!=loaded.Id)throw new InvalidDataException("Sessão diverge da pasta.");Reconcile(loaded);return loaded;}
  void Reconcile(SecureBootSession s){bool installed=false,recovering=false;foreach(bool usb in new[]{true,false}){string id=usb?s.UsbJournalId:s.SsdJournalId;if(id==null)continue;var j=Engine().Load(id);if(j.SessionId!=s.Id||j.CertificateSha256!=s.Identity.CertificateSha256)throw new InvalidDataException("Journal pertence a outra sessão.");if(j.State=="FailedRolledBack"||j.State=="Restored"){if(usb)s.UsbJournalId=null;else s.SsdJournalId=null;}else if(j.State=="Installed"&&!usb)installed=true;else if(j.State!="Installed")recovering=true;}SecureBootWorkflow.ReconcileState(s,installed,recovering);}
  static void Adopt(SecureBootSession target,SecureBootSession source){target.State=source.State;target.UsbJournalId=source.UsbJournalId;target.SsdJournalId=source.SsdJournalId;target.FirmwareTestVerified=source.FirmwareTestVerified;target.WindowsUserConfirmed=source.WindowsUserConfirmed;target.LinuxTestVerified=source.LinuxTestVerified;target.Files=source.Files;target.PreparedUtc=source.PreparedUtc;}
  public List<SecureBootSession> ListSessions(){var result=new List<SecureBootSession>();if(!Directory.Exists(Root))return result;SafeFiles.Plain(Root);foreach(var folder in Directory.GetDirectories(Root)){SafeFiles.Plain(folder);string name=Path.GetFileName(folder);if(!SecureBootWorkflow.Hex(name,32))continue;string path=SafeFiles.Under(folder,"session.json");if(!File.Exists(path))continue;try{result.Add(Reload(new SecureBootSession{Id=name}));}catch(Exception ex){throw new InvalidDataException("Sessão preservada para revisão: "+name+". "+ex.Message,ex);}}result.Sort(delegate(SecureBootSession a,SecureBootSession b){return String.CompareOrdinal(b.CreatedUtc,a.CreatedUtc);});return result;}
  public void ExportCollector(string folder){Administrator();SafeFiles.Plain(folder);Directory.CreateDirectory(folder);SafeFiles.WriteNew(SafeFiles.Under(folder,"collect-secureboot-steamos.sh"),SecureResources.Read("collector"));File.WriteAllText(SafeFiles.Under(folder,"LEIA-ME-coleta.txt"),"No SteamOS instalado, execute:\n  bash collect-secureboot-steamos.sh /caminho/para/nova-pasta-coleta\nCopie a pasta completa de volta ao Windows e selecione-a no assistente.\nO coletor não monta partições, não instala ferramentas e não altera o boot. Não use saída dentro de /boot, /efi ou /esp.\n",new UTF8Encoding(false));}
  public SecureBootSession Prepare(InstallRequest request,string collectionDirectory){
   Administrator();var state=services.Scan();if(request==null||request.Windows==null||!request.Windows.IsWindows||state.SecureBoot==null)throw new InvalidOperationException("Selecione Windows e confirme o estado UEFI.");var part=state.Find(request.Windows.PartitionGuid);if(part==null||!part.IsSystem||!part.IsEsp||part.IsUsb||!part.IsInternal||!String.Equals(part.FileSystem,"FAT32",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Selecione a ESP Windows atual compatível.");
   bool found=false;foreach(var entry in state.Entries)if(entry.Name==request.Windows.Name&&Transaction.Equal(entry.Raw,request.Windows.Raw))found=true;if(!found)throw new IOException("A seleção Windows mudou; verifique novamente.");
   // Existing manual/signed installations may be inspected, but must never be migrated implicitly.
   string existing=SafeFiles.Under(part.Root,@"EFI\DualBoot");if(Directory.Exists(existing)&&!OwnManagedInstallation(part.Root))throw new InvalidOperationException("Há uma instalação personalizada neste PC. Ela será preservada; prepare este fluxo em outro computador ou ambiente de testes.");
   SteamInventory inventory=null;if(request.Steam!=null){if(String.IsNullOrEmpty(collectionDirectory))throw new InvalidOperationException("Importe a coleta do SteamOS antes de preparar a assinatura.");inventory=SteamCollection.Load(collectionDirectory);var actual=state.Find(request.Steam.PartitionGuid);var slot=state.Find(new Guid(inventory.EfiPartitionGuid));var rootfs=state.Find(new Guid(inventory.RootPartitionGuid));if(actual==null||actual.Root==null||actual.IsUsb||!actual.IsInternal||slot==null||rootfs==null||slot.IsUsb||rootfs.IsUsb||!slot.IsInternal||!rootfs.IsInternal||actual.DiskNumber!=slot.DiskNumber||actual.DiskNumber!=rootfs.DiskNumber)throw new InvalidDataException("A coleta não corresponde ao disco e às partições SteamOS selecionados.");}
   Protect();var s=new SecureBootSession{Id=Guid.NewGuid().ToString("N"),CreatedUtc=DateTime.UtcNow.ToString("o"),State="Preparing",Windows=request.Windows,Steam=request.Steam,IncludesSteam=request.Steam!=null,WindowsPartitionGuid=request.Windows.PartitionGuid.ToString(),Timeout=request.Timeout,SteamDefault=request.SteamDefault,SteamFirst=request.SteamFirst,CollectionDirectory=inventory==null?null:Path.GetFullPath(collectionDirectory),RootPartitionGuid=inventory==null?null:inventory.RootPartitionGuid};
   if(inventory!=null){s.SlotPartitionGuid=inventory.EfiPartitionGuid;s.CollectionManifestHash=SafeFiles.Hash(ReadBounded(SafeFiles.Under(s.CollectionDirectory,"collection.json"),65536));}
   string folder=SessionDirectory(s);SafeFiles.CreateDirectoryExclusive(folder);s.Identity=LocalSigner.CreateOrOpen(folder);SaveSession(s);s.WindowsLoaderHash=SafeFiles.HashFile(SafeFiles.Under(part.Root,request.Windows.Path.Substring(1)));
   if(inventory!=null){var steamPart=state.Find(request.Steam.PartitionGuid);s.SteamLoaderHash=SafeFiles.HashFile(SafeFiles.Under(steamPart.Root,request.Steam.Path.Substring(1)));}
   string files=SafeFiles.Under(folder,"payload");Directory.CreateDirectory(files);var payload=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);payload.Add("DualBoot.efi",SecureResources.Read("shim"));payload.Add("mmx64.efi",SecureResources.Read("mokmanager"));payload.Add("DualBoot.cer",Convert.FromBase64String(s.Identity.CertificateBase64));
   payload.Add("grubx64.efi",SignBytes(folder,"menu",PeBinding.Patch(SecureResources.Read("menu"),s.Id,s.Identity.CertificateBase64),s.Identity));payload.Add("Diagnostic.efi",SignBytes(folder,"diagnostic",PeBinding.Patch(SecureResources.Read("diagnostic"),s.Id,s.Identity.CertificateBase64),s.Identity));
   foreach(var pair in Payload.ReadEmbedded())if(pair.Key.StartsWith("themes\\",StringComparison.Ordinal))payload.Add(pair.Key,pair.Value);
   if(inventory!=null){var slot=SteamBundle.Build(inventory,delegate(byte[] kernel){return SignBytes(folder,"kernel",kernel,s.Identity);},s.Id);payload.Add("steam-slot.efi",SignBytes(folder,"steam-slot",PeBinding.EnsureSbat(slot),s.Identity));}
   foreach(var pair in payload){string dest=SafeFiles.Under(files,pair.Key);Directory.CreateDirectory(Path.GetDirectoryName(dest));SafeFiles.WriteNew(dest,pair.Value);}s.Files=SecureBootWorkflow.Records(payload);s.PreparedUtc=DateTime.UtcNow.ToString("o");s.State="AwaitingUsbTest";SaveSession(s);VerifyPayload(s,payload);
   File.WriteAllText(SafeFiles.Under(folder,"ETAPAS.txt"),"Sessão "+s.Id+"\nCertificado SHA256: "+s.Identity.CertificateSha256+"\n\n1. Prepare USB no aplicativo e inicialize seu EFI/BOOT/BOOTX64.EFI.\n2. No MokManager escolha Enroll key from disk e o certificado EFI/BOOT/DualBoot.cer; confira a impressão digital antes de confirmar. Para abrir MokManager com Secure Boot desligado use EFI/BOOT/mmx64.efi pelo firmware, quando disponível.\n3. Ative Secure Boot na BIOS, preservando as bases OEM, e inicie novamente pelo USB. MOK ausente/firmware incompatível exigem revisão; não desative a validação do shim.\n4. Inicie Windows pelo menu USB e copie EFI/BOOT/secureboot-status.txt. Confirme no assistente que Windows iniciou por esse menu.\n"+(s.IncludesSteam?"5. Inicie SteamOS pelo mesmo USB e execute o coletor em modo de verificação:\n bash collect-secureboot-steamos.sh --verify "+s.Id+" "+s.RootPartitionGuid+" /caminho/nova-pasta-relatorio\nImporte secureboot-linux.txt no assistente.\n":"5. Esta sessão prepara SOMENTE Windows; nenhum suporte SteamOS foi incluído.\n")+"6. Retorne ao Windows, valide os relatórios e instale no SSD somente quando liberado. O aplicativo nunca reinicia sozinho.\n\nAtualização SteamOS: mantenha Windows disponível; colete/prepare/teste uma sessão nova após a atualização. Para substituir uma instalação assinada gerenciada antiga, restaure-a primeiro no assistente. Instalações personalizadas não são migradas.\n",new UTF8Encoding(false));return s;
  }
  static byte[] SignBytes(string folder,string name,byte[] input,SigningIdentity identity){string unsigned=SafeFiles.Under(folder,name+"-unsigned.efi"),signed=SafeFiles.Under(folder,name+"-signed.efi");SafeFiles.WriteNew(unsigned,input);LocalSigner.Sign(unsigned,signed,identity);LocalSigner.Verify(signed,identity.CertificateBase64);return ReadBounded(signed,768L*1024*1024);}
  static void VerifyPayload(SecureBootSession s,Dictionary<string,byte[]> payload){
   SecureBootWorkflow.MatchRecords(s,payload);if(SafeFiles.Hash(payload["DualBoot.cer"])!=s.Identity.CertificateSha256||Convert.ToBase64String(payload["DualBoot.cer"])!=s.Identity.CertificateBase64)throw new InvalidDataException("Certificado público diverge.");
   if(SafeFiles.Hash(payload["DualBoot.efi"])!=SafeFiles.Hash(SecureResources.Read("shim"))||SafeFiles.Hash(payload["mmx64.efi"])!=SafeFiles.Hash(SecureResources.Read("mokmanager")))throw new InvalidDataException("Shim/MokManager divergentes.");
   foreach(var name in s.IncludesSteam?new[]{"grubx64.efi","Diagnostic.efi","steam-slot.efi"}:new[]{"grubx64.efi","Diagnostic.efi"}){
    // Verifier reads a bounded owned temporary file; never loads the EFI into Windows.
    string temp=Path.Combine(Path.GetTempPath(),"DualBoot-verify-"+Guid.NewGuid().ToString("N")+".efi");try{SafeFiles.WriteNew(temp,payload[name]);LocalSigner.Verify(temp,s.Identity.CertificateBase64);}finally{if(File.Exists(temp))File.Delete(temp);}
   }
  }
  Dictionary<string,byte[]> PayloadFor(SecureBootSession s){var data=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);string root=SafeFiles.Under(SessionDirectory(s),"payload");foreach(var f in s.Files){byte[] bytes=ReadBounded(SafeFiles.Under(root,f.Path),768L*1024*1024);data.Add(f.Path,bytes);}VerifyPayload(s,data);return data;}
  bool OwnManagedInstallation(string root){if(!Directory.Exists(Root))return false;foreach(var session in ListSessions())if(session.SsdJournalId!=null){var j=Engine().Load(session.SsdJournalId);if(j.State=="Installed"&&j.VolumeIdentity==root){SecureInstallerEngine.VerifyTree(SafeFiles.Under(root,@"EFI\DualBoot"),j,false);return true;}}return false;}
  SecureInstallerEngine Engine(){return new SecureInstallerEngine(firmware,SafeFiles.Under(Root,"transactions"),VerifyPayload);}
  InstallRequest Request(SecureBootSession s){return new InstallRequest{Windows=s.Windows,Steam=s.Steam,Timeout=s.Timeout,SteamDefault=s.SteamDefault,SteamFirst=s.SteamFirst};}
  void ValidateSources(SecureBootSession s,ComputerState state){var win=state.Find(s.Windows.PartitionGuid);if(win==null||win.Root==null||SafeFiles.HashFile(SafeFiles.Under(win.Root,s.Windows.Path.Substring(1)))!=s.WindowsLoaderHash)throw new IOException("O carregador Windows mudou desde a preparação; prepare uma sessão nova.");if(s.IncludesSteam){var p=state.Find(s.Steam.PartitionGuid);if(p==null||p.Root==null||SafeFiles.HashFile(SafeFiles.Under(p.Root,s.Steam.Path.Substring(1)))!=s.SteamLoaderHash)throw new IOException("O carregador SteamOS mudou desde a preparação.");var inventory=SteamCollection.Load(s.CollectionDirectory);if(!String.Equals(inventory.RootPartitionGuid,s.RootPartitionGuid,StringComparison.OrdinalIgnoreCase)||!String.Equals(inventory.EfiPartitionGuid,s.SlotPartitionGuid,StringComparison.OrdinalIgnoreCase)||SafeFiles.Hash(ReadBounded(SafeFiles.Under(s.CollectionDirectory,"collection.json"),65536))!=s.CollectionManifestHash)throw new InvalidDataException("A coleta foi substituída.");}}
  public void PrepareUsb(SecureBootSession selected,PartitionInfo usb){Administrator();var s=Reload(selected);if(s.UsbJournalId!=null&&Engine().Load(s.UsbJournalId).State!="Restored")throw new InvalidOperationException("Restaure o USB anterior desta sessão antes de preparar outro.");var state=services.Scan();ValidateSources(s,state);var request=Request(s);request.UsbPartition=usb;var data=PayloadFor(s);firmware.Initialize();var engine=Engine();engine.JournalPrepared=delegate(SecureDeploymentJournal pending){s.UsbJournalId=pending.Id;SaveSession(s);};var j=engine.Install(state,request,s,data,true,delegate{var fresh=services.Scan();ValidateSources(s,fresh);if(fresh.SecureBoot==null)throw new IOException("Estado Secure Boot desconhecido.");firmware.Initialize();});s.UsbJournalId=j.Id;SaveSession(s);Adopt(selected,s);}
  public void VerifyTest(SecureBootSession selected,string firmwareReportPath,string linuxReportPath,bool windowsConfirmed){
   Administrator();var s=Reload(selected);if(s.UsbJournalId==null)throw new InvalidOperationException("Prepare o USB desta sessão primeiro.");var state=services.Scan();if(state.SecureBoot!=true||!SecureRuntime.Valid(s.Identity.CertificateBase64))throw new InvalidOperationException("O Windows atual não confirmou Secure Boot ativo e o MOK desta sessão com validação habilitada.");ValidateSources(s,state);var usb=Engine().Load(s.UsbJournalId);string usbRoot=Resolve(usb,state);SecureInstallerEngine.VerifyTree(SafeFiles.Under(usbRoot,@"EFI\BOOT"),usb,false);
   string report=new UTF8Encoding(false,true).GetString(ReadBounded(firmwareReportPath,8192));SecureBootWorkflow.AcceptFirmwareReport(s,report,File.GetLastWriteTimeUtc(firmwareReportPath));s.WindowsUserConfirmed=windowsConfirmed;
   if(s.IncludesSteam){string linux=new UTF8Encoding(false,true).GetString(ReadBounded(linuxReportPath,8192));SecureBootWorkflow.AcceptLinuxReport(s,linux,File.GetLastWriteTimeUtc(linuxReportPath));}
   s.State=SecureBootWorkflow.Ready(s)?"ReadyToInstall":"AwaitingUsbTest";SaveSession(s);Adopt(selected,s);
  }
  public void InstallSsd(SecureBootSession selected){Administrator();var s=Reload(selected);if(s.SsdJournalId!=null&&Engine().Load(s.SsdJournalId).State!="Restored")throw new InvalidOperationException("Esta sessão já tem instalação SSD; use Verificar ou Restaurar.");var state=services.Scan();ValidateSources(s,state);if(!SecureRuntime.Valid(s.Identity.CertificateBase64))throw new IOException("MOK/validação desta sessão não foram confirmados no Windows atual.");var data=PayloadFor(s);firmware.Initialize();var engine=Engine();engine.JournalPrepared=delegate(SecureDeploymentJournal pending){s.SsdJournalId=pending.Id;SaveSession(s);};var j=engine.Install(state,Request(s),s,data,false,delegate{var current=services.Scan();ValidateSources(s,current);if(current.SecureBoot!=true||current.EncryptionClear!=true||current.BootNextPending||!SecureRuntime.Valid(s.Identity.CertificateBase64))throw new IOException("Proteções/ambiente mudaram; instalação interrompida.");firmware.Initialize();});s.SsdJournalId=j.Id;s.State="Installed";SaveSession(s);Adopt(selected,s);}
  static string Resolve(SecureDeploymentJournal j,ComputerState state){PartitionInfo found=null;foreach(var p in state.Partitions){bool match=j.Kind=="SSD"?p.Guid.ToString()==j.PartitionGuid:p.Root==j.VolumeIdentity&&p.Guid.ToString()==j.PartitionGuid;if(match){if(found!=null)throw new IOException("Volume ambíguo.");found=p;}}if(found==null||found.Root==null||!String.Equals(found.FileSystem,"FAT32",StringComparison.OrdinalIgnoreCase)||(j.Kind=="SSD"&&(!found.IsEsp||found.IsUsb||!found.IsInternal))||(j.Kind=="USB"&&(!found.IsUsb||found.IsBoot||found.IsSystem)))throw new IOException("Volume registrado não está disponível de forma compatível.");return found.Root;}
  public void VerifyInstalled(SecureBootSession selected){Administrator();var s=Reload(selected);if(s.SsdJournalId==null)throw new InvalidOperationException("Sessão sem instalação SSD.");var state=services.Scan();ValidateSources(s,state);if(state.SecureBoot!=true||!SecureRuntime.Valid(s.Identity.CertificateBase64))throw new IOException("Secure Boot/MOK não confirmados.");var j=Engine().Load(s.SsdJournalId);firmware.Initialize();Engine().Verify(j,Resolve(j,state));}
  public void Restore(SecureBootSession selected,bool usb){Administrator();var s=Reload(selected);string id=usb?s.UsbJournalId:s.SsdJournalId;if(id==null)throw new InvalidOperationException("Não há instalação deste tipo nesta sessão.");var j=Engine().Load(id);var state=services.Scan();string volume=Resolve(j,state);firmware.Initialize();Engine().Restore(j,volume);if(usb)s.UsbJournalId=null;else s.SsdJournalId=null;Reconcile(s);SaveSession(s);Adopt(selected,s);}
 }
 public static class SecureRuntime {
  static readonly string Shim="{605dab50-e046-4300-abb6-3d8e00dd8b23}";
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFirmwareEnvironmentVariableExW(string name,string guid,byte[] buffer,uint size,out uint attrs);
  public static bool Valid(string certificate){try{var f=new NativeFirmware();f.Initialize();uint attrs;byte[] disabled=new byte[1];uint flag=GetFirmwareEnvironmentVariableExW("MokSBStateRT",Shim,disabled,1,out attrs);if(flag==0&&Marshal.GetLastWin32Error()!=203)return false;if(flag>1||(flag==1&&disabled[0]!=0))return false;byte[] data=new byte[1024*1024];uint size=GetFirmwareEnvironmentVariableExW("MokListRT",Shim,data,(uint)data.Length,out attrs);if(size<28||size>data.Length)return false;byte[] cert=Convert.FromBase64String(certificate);int at=0;bool found=false;var x509=new Guid("a5c059a1-94e4-4aa7-87b5-ab155c2bf072");while(at<size){if(size-at<28)return false;byte[] type=new byte[16];Array.Copy(data,at,type,0,16);uint list=BitConverter.ToUInt32(data,at+16),header=BitConverter.ToUInt32(data,at+20),sig=BitConverter.ToUInt32(data,at+24);if(list<28||list>size-at||header>list-28||sig<16||(list-28-header)%sig!=0)return false;int end=checked(at+(int)list);for(int pos=checked(at+28+(int)header);pos<end;pos=checked(pos+(int)sig))if(new Guid(type)==x509&&sig==cert.Length+16){bool equal=true;for(int i=0;i<cert.Length;i++)if(data[pos+16+i]!=cert[i])equal=false;if(equal)found=true;}at=end;}return found&&at==size;}catch{return false;}}
 }
}
